-- V2.4 temporal baseline: never invent inventory before this upgrade.
CREATE TABLE inventory_revisions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,txid bigint NOT NULL UNIQUE,posted_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE inventory_history(bundle_id uuid NOT NULL REFERENCES bundles(id),revision_id bigint NOT NULL REFERENCES inventory_revisions(id),state jsonb NOT NULL,PRIMARY KEY(bundle_id,revision_id));
CREATE INDEX history_revision ON inventory_history(revision_id,bundle_id);
CREATE TABLE document_history(kind text NOT NULL,document_id uuid NOT NULL,revision_id bigint NOT NULL REFERENCES inventory_revisions(id),data jsonb NOT NULL,PRIMARY KEY(kind,document_id,revision_id));
CREATE TABLE inventory_history_boundary(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),started_at timestamptz NOT NULL,event_watermark bigint NOT NULL);
INSERT INTO inventory_history_boundary VALUES(true,clock_timestamp(),coalesce((SELECT max(id) FROM inventory_events),0));
CREATE TABLE inventory_origins(bundle_id uuid PRIMARY KEY REFERENCES bundles(id),opening_qty numeric(14,6) NOT NULL);
CREATE FUNCTION v24_revision() RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r bigint;BEGIN
 PERFORM pg_advisory_xact_lock(24000);SELECT id INTO r FROM inventory_revisions WHERE txid=txid_current();IF r IS NULL THEN INSERT INTO inventory_revisions(txid) VALUES(txid_current()) RETURNING id INTO r;END IF;RETURN r;END $$;
CREATE FUNCTION v24_posting_time() RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r bigint;BEGIN r:=v24_revision();RETURN(SELECT posted_at FROM inventory_revisions WHERE id=r);END $$;
CREATE FUNCTION v24_history_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND current_user='musonoi_owner' AND OLD.revision_id=NEW.revision_id AND EXISTS(SELECT 1 FROM inventory_revisions WHERE id=OLD.revision_id AND txid=txid_current()) THEN RETURN NEW;END IF;RAISE EXCEPTION 'Committed inventory history is immutable' USING ERRCODE='23514';END $$;
CREATE TRIGGER inventory_history_immutable BEFORE UPDATE OR DELETE ON inventory_history FOR EACH ROW EXECUTE FUNCTION v24_history_guard();
CREATE TRIGGER document_history_immutable BEFORE UPDATE OR DELETE ON document_history FOR EACH ROW EXECUTE FUNCTION v24_history_guard();
CREATE TRIGGER revision_immutable BEFORE UPDATE OR DELETE ON inventory_revisions FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER origin_immutable BEFORE UPDATE OR DELETE ON inventory_origins FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER boundary_immutable BEFORE UPDATE OR DELETE ON inventory_history_boundary FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE FUNCTION v24_capture_bundle(bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r bigint;b bundles;s jsonb;BEGIN
 r:=v24_revision();SELECT * INTO b FROM bundles WHERE id=bid;IF NOT FOUND THEN RETURN;END IF;
 INSERT INTO inventory_origins VALUES(b.id,CASE WHEN b.receipt_id IS NULL AND (to_jsonb(b)->>'adjustment_origin_id') IS NULL AND b.physical_status='IN_STOCK' THEN b.net_weight ELSE 0 END) ON CONFLICT DO NOTHING;
 SELECT jsonb_build_object('bundle_id',b.id,'bundle_no',b.bundle_no,'project_id',b.project_id,'customer_id',b.customer_id,'customer',c.name,'batch_id',b.batch_id,'batch',t.code,'location_id',b.location_id,'location',l.code,'warehouse_id',l.warehouse_id,'warehouse',w.code,'yard_id',l.yard_id,'weight',b.net_weight::text,'original_weight',coalesce(to_jsonb(b)->>'original_net_weight',b.net_weight::text),'physical_status',b.physical_status,'sample_status',b.sample_status,'inbound_at',b.inbound_at,'version',b.version,'data_kind',b.data_kind,'allocated_customer_id',p.customer_id,'allocated_customer',ac.name,'reservation_id',rs.id,'locked_at',rs.locked_at,'loading_id',lo.id,'loading_status',lo.status,'vehicle_no',lo.vehicle_no,'loaded_at',lo.completed_at,'dispatched_customer_id',dispatch.customer_id,'outbound_id',dispatch.id) INTO s
 FROM customers c JOIN batches t ON t.id=b.batch_id JOIN locations l ON l.id=b.location_id JOIN warehouses w ON w.id=l.warehouse_id LEFT JOIN reservations rs ON rs.bundle_id=b.id AND rs.released_at IS NULL LEFT JOIN allocations a ON a.id=rs.allocation_id LEFT JOIN sales_plans p ON p.id=a.plan_id LEFT JOIN customers ac ON ac.id=p.customer_id LEFT JOIN loading_items li ON li.bundle_id=b.id AND li.active LEFT JOIN loading_orders lo ON lo.id=li.loading_id LEFT JOIN LATERAL(SELECT o.id,o.customer_id FROM outbound_orders o JOIN loading_items z ON z.loading_id=o.loading_id WHERE z.bundle_id=b.id AND o.status='DEPARTED' AND b.physical_status='OUTBOUND' ORDER BY o.confirmed_at DESC LIMIT 1) dispatch ON true WHERE c.id=b.customer_id;
 INSERT INTO inventory_history VALUES(b.id,r,s) ON CONFLICT(bundle_id,revision_id) DO UPDATE SET state=excluded.state;END $$;
CREATE FUNCTION v24_doc_save(tab text,did uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d jsonb;ids uuid[];ws uuid[];r bigint;child text;key text;BEGIN
 IF tab<>ALL(ARRAY['sampling_batches','weighings','loading_orders','outbound_orders','stocktakes','inventory_exceptions','stock_adjustments']) THEN RAISE EXCEPTION 'Invalid history kind';END IF;
 r:=v24_revision();EXECUTE format('SELECT to_jsonb(d) FROM %I d WHERE id=$1',tab) INTO d USING did;IF d IS NULL THEN RETURN;END IF;
 IF tab='outbound_orders' THEN SELECT array_agg(bundle_id) INTO ids FROM loading_items WHERE loading_id=(d->>'loading_id')::uuid;
 ELSIF tab IN('sampling_batches','weighings','loading_orders') THEN child:=CASE tab WHEN 'sampling_batches' THEN 'sampling_items' WHEN 'weighings' THEN 'weighing_items' ELSE 'loading_items' END;key:=CASE tab WHEN 'sampling_batches' THEN 'sample_id' WHEN 'weighings' THEN 'weighing_id' ELSE 'loading_id' END;EXECUTE format('SELECT array_agg(bundle_id) FROM %I WHERE %I=$1',child,key) INTO ids USING did;END IF;
 IF ids IS NOT NULL THEN SELECT array_agg(DISTINCT l.warehouse_id) INTO ws FROM bundles b JOIN locations l ON l.id=b.location_id WHERE b.id=ANY(ids);ELSE ws:=CASE WHEN d->>'warehouse_id' IS NOT NULL THEN ARRAY[(d->>'warehouse_id')::uuid] ELSE ARRAY[]::uuid[] END;END IF;
 d:=d||jsonb_build_object('bundle_ids',coalesce(ids,ARRAY[]::uuid[]),'warehouse_ids',coalesce(ws,ARRAY[]::uuid[]));INSERT INTO document_history VALUES(tab,did,r,d) ON CONFLICT(kind,document_id,revision_id) DO UPDATE SET data=excluded.data;END $$;
CREATE FUNCTION v24_source_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE bid uuid;did uuid;tab text;BEGIN
 IF TG_TABLE_NAME='bundles' THEN PERFORM v24_capture_bundle(NEW.id);
 ELSIF TG_TABLE_NAME IN('reservations','loading_items','inventory_events') THEN PERFORM v24_capture_bundle(NEW.bundle_id);IF TG_TABLE_NAME='loading_items' THEN PERFORM v24_doc_save('loading_orders',NEW.loading_id);END IF;
 ELSIF TG_TABLE_NAME IN('sampling_items','weighing_items') THEN did:=CASE WHEN TG_TABLE_NAME='sampling_items' THEN NEW.sample_id ELSE NEW.weighing_id END;tab:=CASE WHEN TG_TABLE_NAME='sampling_items' THEN 'sampling_batches' ELSE 'weighings' END;PERFORM v24_doc_save(tab,did);
 ELSE PERFORM v24_doc_save(TG_TABLE_NAME,NEW.id);IF TG_TABLE_NAME IN('loading_orders','outbound_orders') THEN did:=CASE WHEN TG_TABLE_NAME='loading_orders' THEN NEW.id ELSE NEW.loading_id END;FOR bid IN SELECT bundle_id FROM loading_items WHERE loading_id=did LOOP PERFORM v24_capture_bundle(bid);END LOOP;END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER bundles_temporal AFTER INSERT OR UPDATE ON bundles FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE TRIGGER reservation_temporal AFTER INSERT OR UPDATE ON reservations FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE TRIGGER loading_items_temporal AFTER INSERT OR UPDATE ON loading_items FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE TRIGGER sampling_items_temporal AFTER INSERT ON sampling_items FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE TRIGGER weighing_items_temporal AFTER INSERT ON weighing_items FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['sampling_batches','weighings','loading_orders','outbound_orders'] LOOP EXECUTE format('CREATE TRIGGER temporal_document AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION v24_source_capture()',tab);END LOOP;END $$;
ALTER TABLE inventory_events ADD COLUMN revision_id bigint REFERENCES inventory_revisions(id);
CREATE FUNCTION v24_event_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN NEW.revision_id:=v24_revision();NEW.occurred_at:=v24_posting_time();RETURN NEW;END $$;
CREATE TRIGGER event_revision BEFORE INSERT ON inventory_events FOR EACH ROW EXECUTE FUNCTION v24_event_revision();
CREATE TRIGGER event_temporal AFTER INSERT ON inventory_events FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
-- Formal V2.3 departure confirmation and inventory posting now share one serialized database posting time.
DO $$ DECLARE n text;def text;BEGIN FOREACH n IN ARRAY ARRAY['confirm_receipt(uuid,uuid,integer)','sampling_action(uuid,uuid,integer,text,text)','weighing_action(uuid,uuid,integer,text,text)','loading_action(uuid,uuid,integer,text,text)','outbound_action(uuid,uuid,integer,text,jsonb)','confirm_stock_move(uuid,uuid)'] LOOP SELECT pg_get_functiondef(n::regprocedure) INTO def;EXECUTE replace(def,'now()','v24_posting_time()');END LOOP;END $$;
CREATE FUNCTION v24_visible(actor uuid,s jsonb,f jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT s IS NOT NULL AND EXISTS(SELECT 1 FROM user_scopes u WHERE u.user_id=actor AND u.project_id=(s->>'project_id')::uuid AND(u.customer_id IS NULL OR u.customer_id=(s->>'customer_id')::uuid OR u.customer_id=(s->>'allocated_customer_id')::uuid OR u.customer_id=(s->>'dispatched_customer_id')::uuid) AND(u.warehouse_id IS NULL OR u.warehouse_id=(s->>'warehouse_id')::uuid)) AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(f) k WHERE k.key IN('project_id','customer_id','warehouse_id','yard_id','location_id','batch_id','allocated_customer_id') AND nullif(k.value,'') IS NOT NULL AND s->>k.key IS DISTINCT FROM k.value) $$;
CREATE FUNCTION v24_qty(actor uuid,s jsonb,f jsonb) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE WHEN v24_visible(actor,s,f) AND s->>'physical_status'='IN_STOCK' THEN(s->>'weight')::numeric ELSE 0::numeric END $$;
CREATE FUNCTION v24_doc_visible(actor uuid,d jsonb,f jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM user_scopes u WHERE u.user_id=actor AND u.project_id=(d->>'project_id')::uuid AND(u.customer_id IS NULL OR u.customer_id=(d->>'customer_id')::uuid) AND(u.warehouse_id IS NULL OR(jsonb_array_length(d->'warehouse_ids')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(d->'warehouse_ids') w WHERE w::uuid<>u.warehouse_id)))) AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(f) k WHERE k.key IN('project_id','customer_id','warehouse_id') AND nullif(k.value,'') IS NOT NULL AND CASE WHEN k.key='warehouse_id' THEN NOT(coalesce(d->'warehouse_ids','[]') ? k.value) ELSE d->>k.key IS DISTINCT FROM k.value END) $$;
DO $$ DECLARE b bundles;tab text;did uuid;BEGIN
 FOR b IN SELECT * FROM bundles LOOP INSERT INTO inventory_origins VALUES(b.id,CASE WHEN b.physical_status='IN_STOCK' THEN b.net_weight ELSE 0 END);PERFORM v24_capture_bundle(b.id);END LOOP;
 FOREACH tab IN ARRAY ARRAY['sampling_batches','weighings','loading_orders','outbound_orders'] LOOP FOR did IN EXECUTE format('SELECT id FROM %I',tab) LOOP PERFORM v24_doc_save(tab,did);END LOOP;END LOOP;END $$;
REVOKE ALL ON FUNCTION v24_capture_bundle(uuid),v24_doc_save(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION v24_revision(),v24_posting_time(),v24_visible(uuid,jsonb,jsonb),v24_qty(uuid,jsonb,jsonb),v24_doc_visible(uuid,jsonb,jsonb) TO musonoi_app;
GRANT SELECT ON inventory_revisions,inventory_history,document_history,inventory_history_boundary,inventory_origins TO musonoi_app;
INSERT INTO permissions VALUES('stocktake:read'),('stocktake:write'),('stocktake:review'),('exception:read'),('exception:write'),('exception:review'),('exception:configure'),('adjust:read'),('adjust:write'),('adjust:approve'),('report:read'),('dashboard:read');
INSERT INTO role_permissions SELECT r.code,p.code FROM roles r CROSS JOIN permissions p WHERE(r.code IN('admin','supervisor','operator','production') AND p.code IN('stocktake:read','stocktake:write','exception:read','exception:write','adjust:read','adjust:write')) OR(r.code IN('admin','supervisor') AND p.code IN('stocktake:review','exception:review','adjust:approve')) OR(r.code='admin' AND p.code='exception:configure') OR p.code IN('report:read','dashboard:read') ON CONFLICT DO NOTHING;
